INSERT INTO public.questions (category_id, texts, question_type, have_answers, answers, order_index)
VALUES
('daily_love_language', '{"text_en": "After a hard day, what helps you most?", "text_tr": "Zor bir günün sonunda sana en çok ne iyi gelir?", "text_es": "Después de un día difícil, ¿qué te ayuda más?", "text_pt": "Depois de um dia difícil, o que mais te ajuda?"}'::jsonb, 'choice', true, '{"answers_en": ["A long hug", "Talking it through", "Them taking something off my plate", "A little time alone first"], "answers_tr": ["Uzun bir sarılma", "Konuşup içimi dökmek", "Bir işimi üstlenmesi", "Önce biraz yalnız kalmak"], "answers_es": ["Un abrazo largo", "Hablarlo", "Que se encargue de algo por mí", "Un rato a solas primero"], "answers_pt": ["Um abraço demorado", "Conversar sobre isso", "Que assuma alguma tarefa por mim", "Um tempo sozinho primeiro"]}'::jsonb, 1),
('daily_love_language', '{"text_en": "When do you feel most loved by your partner?", "text_tr": "Partnerin tarafından en çok ne zaman sevildiğini hissedersin?", "text_es": "¿Cuándo te sientes más querido/a por tu pareja?", "text_pt": "Quando você se sente mais amado(a) pelo parceiro?"}'::jsonb, 'choice', true, '{"answers_en": ["When they tell me", "When they make time for me", "When they do things for me", "When they touch me for no reason"], "answers_tr": ["Bana söylediğinde", "Bana vakit ayırdığında", "Benim için bir şey yaptığında", "Sebepsizce dokunduğunda"], "answers_es": ["Cuando me lo dice", "Cuando me dedica tiempo", "Cuando hace cosas por mí", "Cuando me toca sin motivo"], "answers_pt": ["Quando me diz", "Quando reserva tempo pra mim", "Quando faz coisas por mim", "Quando me toca sem motivo"]}'::jsonb, 2),
('daily_love_language', '{"text_en": "Which gift would mean the most to you?", "text_tr": "Hangi hediye senin için en anlamlı olurdu?", "text_es": "¿Qué regalo significaría más para ti?", "text_pt": "Que presente significaria mais pra você?"}'::jsonb, 'choice', true, '{"answers_en": ["A handwritten letter", "A day planned just for us", "Something I mentioned once and forgot", "No gift, just undivided attention"], "answers_tr": ["El yazısıyla bir mektup", "Sadece bize planlanmış bir gün", "Bir kez bahsedip unuttuğum bir şey", "Hediye değil, tam ilgi"], "answers_es": ["Una carta escrita a mano", "Un día planeado solo para nosotros", "Algo que mencioné una vez y olvidé", "Ningún regalo, solo toda su atención"], "answers_pt": ["Uma carta escrita à mão", "Um dia planejado só para nós", "Algo que mencionei uma vez e esqueci", "Nenhum presente, só atenção total"]}'::jsonb, 3),
('daily_love_language', '{"text_en": "How do you usually show love without saying it?", "text_tr": "Söylemeden sevgini genelde nasıl gösterirsin?", "text_es": "¿Cómo sueles demostrar amor sin decirlo?", "text_pt": "Como você costuma demonstrar amor sem dizer?"}'::jsonb, 'choice', true, '{"answers_en": ["Taking care of things", "Little touches", "Remembering details", "Making them laugh"], "answers_tr": ["İşleri halletmek", "Küçük dokunuşlar", "Detayları hatırlamak", "Onu güldürmek"], "answers_es": ["Ocupándome de cosas", "Pequeñas caricias", "Recordando detalles", "Haciéndole reír"], "answers_pt": ["Cuidando das coisas", "Pequenos toques", "Lembrando detalhes", "Fazendo rir"]}'::jsonb, 4),
('daily_love_language', '{"text_en": "What would hurt you more?", "text_tr": "Hangisi seni daha çok kırar?", "text_es": "¿Qué te dolería más?", "text_pt": "O que te magoaria mais?"}'::jsonb, 'choice', true, '{"answers_en": ["A forgotten special day", "Being ignored for a phone", "A cold reply when I open up", "Not being defended in front of others"], "answers_tr": ["Unutulan özel bir gün", "Telefon yüzünden görmezden gelinmek", "Açıldığımda soğuk bir cevap", "Başkalarının önünde savunulmamak"], "answers_es": ["Un día especial olvidado", "Que me ignore por el móvil", "Una respuesta fría cuando me abro", "Que no me defienda delante de otros"], "answers_pt": ["Um dia especial esquecido", "Ser ignorado por causa do celular", "Uma resposta fria quando me abro", "Não ser defendido na frente dos outros"]}'::jsonb, 5),
('daily_love_language', '{"text_en": "How often do you want to hear “I love you”?", "text_tr": "“Seni seviyorum”u ne sıklıkla duymak istersin?", "text_es": "¿Con qué frecuencia quieres oír “te quiero”?", "text_pt": "Com que frequência você quer ouvir “eu te amo”?"}'::jsonb, 'choice', true, '{"answers_en": ["Several times a day", "Once a day is perfect", "Only when it really means something", "I''d rather see it than hear it"], "answers_tr": ["Günde birkaç kez", "Günde bir kez yeter", "Sadece gerçekten anlam taşıdığında", "Duymaktan çok görmek isterim"], "answers_es": ["Varias veces al día", "Una vez al día es perfecto", "Solo cuando de verdad significa algo", "Prefiero verlo que oírlo"], "answers_pt": ["Várias vezes ao dia", "Uma vez por dia está ótimo", "Só quando realmente significa algo", "Prefiro ver do que ouvir"]}'::jsonb, 6),
('daily_love_language', '{"text_en": "In a few words: what makes you feel most loved?", "text_tr": "Birkaç kelimeyle: seni en çok ne sevildiğini hissettirir?", "text_es": "En pocas palabras: ¿qué te hace sentir más querido/a?", "text_pt": "Em poucas palavras: o que mais te faz se sentir amado(a)?"}'::jsonb, 'text', false, NULL, 7),
('daily_love_language', '{"text_en": "What is one thing you wish your partner did more often?", "text_tr": "Partnerinin daha sık yapmasını istediğin bir şey ne?", "text_es": "¿Qué te gustaría que tu pareja hiciera más a menudo?", "text_pt": "O que você gostaria que seu parceiro fizesse com mais frequência?"}'::jsonb, 'text', false, NULL, 8),
('daily_conflict', '{"text_en": "When an argument starts, what do you do first?", "text_tr": "Bir tartışma başladığında ilk ne yaparsın?", "text_es": "Cuando empieza una discusión, ¿qué haces primero?", "text_pt": "Quando uma discussão começa, o que você faz primeiro?"}'::jsonb, 'choice', true, '{"answers_en": ["Say everything right away", "Go quiet", "Try to calm things down", "Leave the room for a while"], "answers_tr": ["Her şeyi hemen söylerim", "Susarım", "Ortamı yumuşatmaya çalışırım", "Bir süre odadan çıkarım"], "answers_es": ["Lo digo todo de inmediato", "Me quedo callado/a", "Intento calmar las cosas", "Salgo un rato de la habitación"], "answers_pt": ["Falo tudo na hora", "Fico em silêncio", "Tento acalmar as coisas", "Saio do cômodo um pouco"]}'::jsonb, 1),
('daily_conflict', '{"text_en": "What ends a fight fastest for you?", "text_tr": "Bir kavgayı senin için en hızlı ne bitirir?", "text_es": "¿Qué termina una pelea más rápido para ti?", "text_pt": "O que faz uma briga acabar mais rápido pra você?"}'::jsonb, 'choice', true, '{"answers_en": ["A sincere apology", "A hug, no words", "Talking it all out", "Some time and space"], "answers_tr": ["Samimi bir özür", "Sözsüz bir sarılma", "Her şeyi konuşup bitirmek", "Biraz zaman ve alan"], "answers_es": ["Una disculpa sincera", "Un abrazo, sin palabras", "Hablarlo todo", "Algo de tiempo y espacio"], "answers_pt": ["Um pedido de desculpas sincero", "Um abraço, sem palavras", "Conversar sobre tudo", "Um pouco de tempo e espaço"]}'::jsonb, 2),
('daily_conflict', '{"text_en": "Is it okay to go to bed angry?", "text_tr": "Küs yatmak olur mu?", "text_es": "¿Está bien irse a dormir enfadados?", "text_pt": "Tudo bem ir dormir brigados?"}'::jsonb, 'choice', true, '{"answers_en": ["Never", "Sometimes it''s better to sleep on it", "Depends on the fight"], "answers_tr": ["Asla", "Bazen üzerine uyumak daha iyi", "Kavgaya göre değişir"], "answers_es": ["Nunca", "A veces es mejor consultarlo con la almohada", "Depende de la pelea"], "answers_pt": ["Nunca", "Às vezes é melhor dormir e pensar", "Depende da briga"]}'::jsonb, 3),
('daily_conflict', '{"text_en": "What do you need most when you''re upset?", "text_tr": "Üzgünken en çok neye ihtiyaç duyarsın?", "text_es": "¿Qué necesitas más cuando estás molesto/a?", "text_pt": "Do que você mais precisa quando está chateado(a)?"}'::jsonb, 'choice', true, '{"answers_en": ["To be listened to, not fixed", "A solution", "To be left alone for a bit", "To hear that we''re okay"], "answers_tr": ["Çözülmek değil, dinlenmek", "Bir çözüm", "Biraz yalnız bırakılmak", "İyi olduğumuzu duymak"], "answers_es": ["Que me escuchen, no que me arreglen", "Una solución", "Que me dejen solo/a un rato", "Saber que estamos bien"], "answers_pt": ["Ser ouvido(a), não consertado(a)", "Uma solução", "Ficar sozinho(a) um pouco", "Saber que estamos bem"]}'::jsonb, 4),
('daily_conflict', '{"text_en": "What do you two argue about most?", "text_tr": "En çok ne hakkında tartışırsınız?", "text_es": "¿Sobre qué discuten más?", "text_pt": "Sobre o que vocês mais discutem?"}'::jsonb, 'choice', true, '{"answers_en": ["Chores and responsibilities", "Time and attention", "Plans and being late", "Small things that add up"], "answers_tr": ["Ev işleri ve sorumluluklar", "Zaman ve ilgi", "Planlar ve geç kalmak", "Birikip büyüyen küçük şeyler"], "answers_es": ["Tareas y responsabilidades", "Tiempo y atención", "Planes y llegar tarde", "Cosas pequeñas que se acumulan"], "answers_pt": ["Tarefas e responsabilidades", "Tempo e atenção", "Planos e atrasos", "Coisinhas que se acumulam"]}'::jsonb, 5),
('daily_conflict', '{"text_en": "After a fight, how long until you feel close again?", "text_tr": "Bir kavgadan sonra tekrar yakın hissetmen ne kadar sürer?", "text_es": "Después de una pelea, ¿cuánto tardas en volver a sentirte cerca?", "text_pt": "Depois de uma briga, quanto tempo até você se sentir próximo(a) de novo?"}'::jsonb, 'choice', true, '{"answers_en": ["Minutes", "A few hours", "A day or more", "Until we really talk it through"], "answers_tr": ["Dakikalar", "Birkaç saat", "Bir gün ya da daha fazla", "Gerçekten konuşana kadar"], "answers_es": ["Minutos", "Unas horas", "Un día o más", "Hasta que lo hablamos de verdad"], "answers_pt": ["Minutos", "Algumas horas", "Um dia ou mais", "Até a gente conversar de verdade"]}'::jsonb, 6),
('daily_conflict', '{"text_en": "Which sentence calms you down instantly during an argument?", "text_tr": "Tartışma sırasında seni anında sakinleştiren cümle hangisi?", "text_es": "¿Qué frase te calma al instante en una discusión?", "text_pt": "Qual frase te acalma na hora durante uma discussão?"}'::jsonb, 'text', false, NULL, 7),
('daily_conflict', '{"text_en": "What is one thing you wish you did differently when you argue?", "text_tr": "Tartışırken farklı yapmayı dilediğin bir şey ne?", "text_es": "¿Qué te gustaría hacer diferente cuando discuten?", "text_pt": "O que você gostaria de fazer diferente quando vocês discutem?"}'::jsonb, 'text', false, NULL, 8),
('daily_everyday_life', '{"text_en": "Your ideal weekday evening together?", "text_tr": "Birlikte ideal hafta içi akşamınız?", "text_es": "¿Su noche ideal entre semana juntos?", "text_pt": "A noite ideal de vocês num dia de semana?"}'::jsonb, 'choice', true, '{"answers_en": ["Cooking together", "Series on the couch", "Going out somewhere", "Side by side, each doing our own thing"], "answers_tr": ["Birlikte yemek yapmak", "Kanepede dizi", "Bir yere çıkmak", "Yan yana, herkes kendi işinde"], "answers_es": ["Cocinar juntos", "Series en el sofá", "Salir a algún sitio", "Uno al lado del otro, cada uno a lo suyo"], "answers_pt": ["Cozinhar juntos", "Série no sofá", "Sair para algum lugar", "Lado a lado, cada um na sua"]}'::jsonb, 1),
('daily_everyday_life', '{"text_en": "Mornings for you are…", "text_tr": "Senin için sabahlar…", "text_es": "Para ti, las mañanas son…", "text_pt": "Pra você, as manhãs são…"}'::jsonb, 'choice', true, '{"answers_en": ["My best time", "Quiet, please", "A race against the clock", "Better with coffee in bed"], "answers_tr": ["Günün en iyi anı", "Lütfen sessizlik", "Saatle yarış", "Yatakta kahveyle daha güzel"], "answers_es": ["Mi mejor momento", "Silencio, por favor", "Una carrera contra el reloj", "Mejores con café en la cama"], "answers_pt": ["Meu melhor momento", "Silêncio, por favor", "Uma corrida contra o relógio", "Melhores com café na cama"]}'::jsonb, 2),
('daily_everyday_life', '{"text_en": "Which chore would you happily never do again?", "text_tr": "Bir daha hiç yapmasan sevineceğin ev işi hangisi?", "text_es": "¿Qué tarea de casa no volverías a hacer nunca?", "text_pt": "Qual tarefa de casa você adoraria nunca mais fazer?"}'::jsonb, 'choice', true, '{"answers_en": ["Dishes", "Laundry", "Cleaning the bathroom", "Grocery shopping"], "answers_tr": ["Bulaşık", "Çamaşır", "Banyo temizliği", "Market alışverişi"], "answers_es": ["Fregar los platos", "La ropa", "Limpiar el baño", "Hacer la compra"], "answers_pt": ["Lavar a louça", "Lavar roupa", "Limpar o banheiro", "Fazer mercado"]}'::jsonb, 3),
('daily_everyday_life', '{"text_en": "How much time alone do you need in a normal week?", "text_tr": "Normal bir haftada ne kadar yalnız zamana ihtiyaç duyarsın?", "text_es": "¿Cuánto tiempo a solas necesitas en una semana normal?", "text_pt": "De quanto tempo sozinho(a) você precisa numa semana normal?"}'::jsonb, 'choice', true, '{"answers_en": ["Almost none", "An hour or two", "An evening or more", "A lot, and I don''t always say it"], "answers_tr": ["Neredeyse hiç", "Bir iki saat", "Bir akşam ya da daha fazla", "Çok, ve bunu hep söylemem"], "answers_es": ["Casi nada", "Una o dos horas", "Una tarde o más", "Mucho, y no siempre lo digo"], "answers_pt": ["Quase nada", "Uma ou duas horas", "Uma noite ou mais", "Muito, e nem sempre eu digo"]}'::jsonb, 4),
('daily_everyday_life', '{"text_en": "What makes an ordinary day feel special?", "text_tr": "Sıradan bir günü özel hissettiren ne?", "text_es": "¿Qué hace que un día normal se sienta especial?", "text_pt": "O que faz um dia comum parecer especial?"}'::jsonb, 'choice', true, '{"answers_en": ["An unexpected message", "A meal we didn''t plan", "Laughing at something silly", "A walk with no destination"], "answers_tr": ["Beklenmedik bir mesaj", "Plansız bir yemek", "Saçma bir şeye gülmek", "Amaçsız bir yürüyüş"], "answers_es": ["Un mensaje inesperado", "Una comida sin planear", "Reírnos de una tontería", "Un paseo sin destino"], "answers_pt": ["Uma mensagem inesperada", "Uma refeição não planejada", "Rir de uma bobagem", "Uma caminhada sem destino"]}'::jsonb, 5),
('daily_everyday_life', '{"text_en": "How tidy should home be?", "text_tr": "Ev ne kadar düzenli olmalı?", "text_es": "¿Qué tan ordenada debe estar la casa?", "text_pt": "Quão arrumada a casa deve estar?"}'::jsonb, 'choice', true, '{"answers_en": ["Spotless", "Tidy enough", "Lived-in is cozy", "I don''t notice the mess"], "answers_tr": ["Pırıl pırıl", "Yeterince toplu", "Biraz dağınık daha samimi", "Dağınıklığı fark etmem"], "answers_es": ["Impecable", "Lo bastante ordenada", "Un poco de desorden es acogedor", "No noto el desorden"], "answers_pt": ["Impecável", "Arrumada o suficiente", "Um pouco bagunçada é aconchegante", "Nem percebo a bagunça"]}'::jsonb, 6),
