('daily_trust_jealousy', '{"text_en": "Is it okay to look at your partner''s phone?", "text_tr": "Partnerinin telefonuna bakmak olur mu?", "text_es": "¿Está bien mirar el móvil de tu pareja?", "text_pt": "Tudo bem olhar o celular do parceiro?"}'::jsonb, 'choice', true, '{"answers_en": ["Never", "Only with permission", "Yes, we have nothing to hide"], "answers_tr": ["Asla", "Sadece izinle", "Evet, saklayacak bir şeyimiz yok"], "answers_es": ["Nunca", "Solo con permiso", "Sí, no tenemos nada que ocultar"], "answers_pt": ["Nunca", "Só com permissão", "Sim, não temos nada a esconder"]}'::jsonb, 1),
('daily_trust_jealousy', '{"text_en": "Someone gives your partner a lot of attention. You…", "text_tr": "Biri partnerine çok ilgi gösteriyor. Sen…", "text_es": "Alguien le presta mucha atención a tu pareja. Tú…", "text_pt": "Alguém dá muita atenção ao seu parceiro. Você…"}'::jsonb, 'choice', true, '{"answers_en": ["Don''t mind at all", "Feel a small sting but trust them", "Would want to talk about it", "Would get openly jealous"], "answers_tr": ["Hiç umursamam", "Hafif bir sızı ama güvenirim", "Konuşmak isterim", "Açıkça kıskanırım"], "answers_es": ["No me importa en absoluto", "Siento una punzada, pero confío", "Querría hablarlo", "Me pondría celoso/a abiertamente"], "answers_pt": ["Não ligo nem um pouco", "Sinto uma pontinha, mas confio", "Ia querer conversar", "Ficaria com ciúme abertamente"]}'::jsonb, 2),
('daily_trust_jealousy', '{"text_en": "Staying friends with an ex is…", "text_tr": "Eski sevgiliyle arkadaş kalmak…", "text_es": "Seguir siendo amigo de un ex es…", "text_pt": "Continuar amigo de um ex é…"}'::jsonb, 'choice', true, '{"answers_en": ["Totally fine", "Fine if there''s nothing left", "Uncomfortable for me", "A dealbreaker"], "answers_tr": ["Tamamen normal", "Hiçbir şey kalmadıysa sorun değil", "Beni rahatsız eder", "Kabul edilemez"], "answers_es": ["Totalmente normal", "Bien si no queda nada", "Me incomoda", "Inaceptable"], "answers_pt": ["Totalmente normal", "Ok se não sobrou nada", "Me incomoda", "Inaceitável"]}'::jsonb, 3),
('daily_trust_jealousy', '{"text_en": "What breaks your trust the fastest?", "text_tr": "Güvenini en hızlı ne sarsar?", "text_es": "¿Qué rompe tu confianza más rápido?", "text_pt": "O que quebra sua confiança mais rápido?"}'::jsonb, 'choice', true, '{"answers_en": ["A small lie", "A broken promise", "Secrets with others", "Hidden feelings"], "answers_tr": ["Küçük bir yalan", "Tutulmayan bir söz", "Başkalarıyla sırlar", "Saklanan duygular"], "answers_es": ["Una pequeña mentira", "Una promesa rota", "Secretos con otros", "Sentimientos ocultos"], "answers_pt": ["Uma mentirinha", "Uma promessa quebrada", "Segredos com outras pessoas", "Sentimentos escondidos"]}'::jsonb, 4),
('daily_trust_jealousy', '{"text_en": "How much should you know about each other''s day?", "text_tr": "Birbirinizin gününü ne kadar bilmelisiniz?", "text_es": "¿Cuánto deberían saber del día del otro?", "text_pt": "Quanto vocês deveriam saber do dia um do outro?"}'::jsonb, 'choice', true, '{"answers_en": ["Everything, minute by minute", "The highlights", "Only what we want to share"], "answers_tr": ["Her şeyi, dakika dakika", "Önemli anları", "Sadece paylaşmak istediklerimizi"], "answers_es": ["Todo, minuto a minuto", "Lo más importante", "Solo lo que queramos contar"], "answers_pt": ["Tudo, minuto a minuto", "Os destaques", "Só o que quisermos contar"]}'::jsonb, 5),
('daily_trust_jealousy', '{"text_en": "Do you feel jealous more often than you show?", "text_tr": "Gösterdiğinden daha sık kıskanır mısın?", "text_es": "¿Sientes celos más a menudo de lo que muestras?", "text_pt": "Você sente ciúme com mais frequência do que demonstra?"}'::jsonb, 'choice', true, '{"answers_en": ["Yes, quite often", "Sometimes", "Rarely", "Never"], "answers_tr": ["Evet, oldukça sık", "Bazen", "Nadiren", "Asla"], "answers_es": ["Sí, bastante a menudo", "A veces", "Rara vez", "Nunca"], "answers_pt": ["Sim, com frequência", "Às vezes", "Raramente", "Nunca"]}'::jsonb, 6),
('daily_trust_jealousy', '{"text_en": "What makes you feel completely safe in this relationship?", "text_tr": "Bu ilişkide kendini tamamen güvende hissettiren ne?", "text_es": "¿Qué te hace sentir completamente seguro/a en esta relación?", "text_pt": "O que te faz se sentir totalmente seguro(a) nesta relação?"}'::jsonb, 'text', false, NULL, 7),
